-- F-230: characters on a baked accessory colour move to its clean colour + that accessory (customization 5).
-- GENERATED by Scripts/Character Skins/accessories.py - do not edit, re-run the script. Idempotent: the
-- customization is stored first, keyed by the baked colour, then the colour moves.
-- Scourge Female 25 -> 28 + Accessories 1 (Spiked harness, violet)
INSERT INTO character_customizations (guid, customization, choice) SELECT guid, 5, 1 FROM characters WHERE race = 5 AND gender = 1 AND skin = 25 ON DUPLICATE KEY UPDATE choice = 1;
UPDATE characters SET skin = 28 WHERE race = 5 AND gender = 1 AND skin = 25;
-- Scourge Female 26 -> 29 + Accessories 2 (Spiked harness, crimson)
INSERT INTO character_customizations (guid, customization, choice) SELECT guid, 5, 2 FROM characters WHERE race = 5 AND gender = 1 AND skin = 26 ON DUPLICATE KEY UPDATE choice = 2;
UPDATE characters SET skin = 29 WHERE race = 5 AND gender = 1 AND skin = 26;
